 let t=Math.round(base-(c[1]-cap[1])*.7+(R()*8-4));const wet=WET8[S.nation]||1;let L;
 if(t<=1)L=[['Karlı','🌨',2*wet],['Ayaz','❄',3],['Sisli','🌫',1],['Açık','☀',2]];
 else if(t>=31)L=[['Kavurucu sıcak','🔥',3],['Açık','☀',3],['Rüzgârlı','🌬',1],['Toz fırtınası','🌪',S.nation==='SUR'||S.nation==='PAK'||S.nation==='UZB'?1.5:.2]];
 else L=[['Açık','☀',3/wet],['Parçalı bulutlu','⛅',2.5],['Yağmurlu','🌧',2*wet],['Sisli','🌫',.8*wet],['Rüzgârlı','🌬',1.2]];
 let s=L.reduce((a,x)=>a+x[2],0)*R();let w=L[0];for(const x of L){s-=x[2];if(s<=0){w=x;break}}
