const CKIA8={sert:['{n} artık aramızda değil. Ailesine yazacağın mektubu ben de okuyacağım.'],babacan:['{n}… Allah rahmet eylesin. Bu yük ikimizin omzunda, unutma.'],soguk:['{n} kaybını kayda geçirdim. Kayıp, planlamada bir değişkendi; bundan ders çıkaracağız.']};
const CSIV8={sert:['Sivillerin zarar gördüğü iddiası var. Bunun hesabını ben değil, sen vereceksin.'],babacan:['Sivillerin zarar gördüğünü duydum. Bu bizim yolumuz değil evlat.'],soguk:['Sivil zarar raporu, harekâtın siyasi maliyetini ikiye katladı.']};
const CGIZ8={sert:['Düşman sizi son ana kadar görmedi. Gizlilik böyle korunur.'],babacan:['Hiç görünmeden girip çıkmışsınız. Aferin.'],soguk:['Gizlilik değerin hedeflenenin üstünde. Sürpriz faktörü işe yaradı.']};
const CFIT8={sert:['Tertip seçimin isabetliydi; hazırlığı ciddiye almışsın.'],babacan:['Hazırlığı iyi yapmışsın, yarısı oradan geldi.'],soguk:['Tertip ve destek seçimin görevin profiline uyuyordu.']};
const CNOFIT8={sert:['Bu göreve bu tertiple gidilmez. Hazırlığı baştan öğreneceksin.'],babacan:['Tertibi biraz aceleyle seçmişsin gibi geldi bana.'],soguk:['Tertip seçimin görev profiliyle uyumsuzdu; bu da kayıp oranına yansıdı.']};
const CREP8={sorumluluk:'Sorumluluk benim, komutanım.',adamlar:'Başarı birliğimin. {m} özellikle takdiri hak ediyor.',aile:'{n} ailesine haberi ben vermek istiyorum.',savun:'O kararı neden verdiğimi açıklamama izin verin.',hirs:'Bir sonraki görevde daha büyük sorumluluk istiyorum.',egitim:'Hatamdan ders aldım; ek eğitim talep ediyorum.',kaynak:'Daha fazla destek ve kaynak gerekiyor.',sivil:'Sivil zarar iddialarını şahsen soruşturacağım.'};
const CRESP8={
 sorumluluk:{sert:['Sorumluluk alan subay, emir veren subaydan değerlidir. Kabul ediyorum.','Sorumluluk almak yetmez; aynı hatayı tekrarlamayacaksın.'],babacan:['Yükü sırtlanman güzel ama tek başına taşıma.','Ağır bir gündü. Sorumluluğu birlikte taşıyacağız.'],soguk:['Kayda geçti. Şimdi bir sonraki adımı konuşalım.','Sorumluluk bir duygu değil, bir süreçtir. Hata analizini getir.']},
 adamlar:{sert:['İyi savaştılar. {m} için takdirname imzalıyorum.','Adamlarını övmeden önce kendi planını düzelt.'],babacan:['Bak bu hoşuma gitti. Adamlarını kollayan komutanı adamları da kollar.','Onlar da yorgun. Bu akşam yanlarında ol.'],soguk:['Performans verileri bunu destekliyor. Takdir yazısını onaylıyorum.','Veriler bu yorumu desteklemiyor.']},
 aile:{sert:['…Bu doğru olan. Git, üniformanı düzelt ve git.','Doğru olan bu.'],babacan:['Gözlerin dolu. Git evlat, ben de seninle geleceğim.','Seninle geleceğim.'],soguk:['Uygun görüyorum. Prosedür için personel şubesiyle görüş.','Uygun.']},
 savun:{sert:['Dinliyorum. …Mantıklı. Ama sahada bunu bir daha anlatmana gerek kalmasın.','Mazeret dinlemem! Hazır ol!'],babacan:['Anlattıkların mantıklı. Belki ben de öyle yapardım.','Evlat, bazen kendini savunmak yerine dinlemek gerekir.'],soguk:['Gerekçen tutarlı. Kararı yeniden değerlendirdim; kısmen haklısın.','Gerekçen verilerle örtüşmüyor.']},
 hirs:{sert:['İşte istediğim cevap. Yarın sana zor bir görev vereceğim.','Önce bugünkü işi düzgün yap, sonra büyük konuş.'],babacan:['Hırsın güzel ama ayağını yere bas. Yarın daha zorunu vereceğim, dikkat et.','Acele etme evlat; sıra sana da gelecek.'],soguk:['Kapasiten bunu kaldırır. Yarınki görev daha karmaşık olacak.','Talebin şu an için erken.']},
 egitim:{sert:['Yarın 05:00\'te poligondasın. Ben de orada olacağım.','Yarın 05:00\'te poligondasın.'],babacan:['Öğrenmek isteyen kimseyi geri çevirmem. Yarın birlikte harita çalışalım.','Güzel. Yarın birlikte çalışırız.'],soguk:['Talebin onaylandı. Kurmay okulunun simülasyon modülünü alacaksın.','Onaylandı.']},
 kaynak:{sert:['Kaynak istemek kolay. Önce elindekini verimli kullan.','Eksiklerini yazılı getir. Haklıysan veririm.'],babacan:['Haklısın, ikmal birimini arayacağım.','Elimizden geleni yapacağız; ama sabır da lazım.'],soguk:['Talebin mantıklı. Ek İHA tahsisini onaylıyorum.','Kaynak artışının etkisini rakamlarla göster.']},
 sivil:{sert:['Doğru. Soruşturma raporunu bana getir; örtbas yok.','Doğru.'],babacan:['İşte bu yüzden sana güveniyorum.','Doğru olanı yapıyorsun.'],soguk:['Şeffaflık siyasi maliyeti düşürür. Onaylıyorum.','Onaylandı.']}};
function cmdrTalk(res,line){const P=CMDP[S.cmdP]?S.cmdP:'sert';const c=(S.mRes&&S.mRes.ctx)||{res};const kn=(c.kia||[])[0];
 const parts=[pick(COP8[P]),line.replace(/^"|"$/g,'')];
 if(c.best&&c.best[2]>=.8)parts.push(fill(pick(CBEST8[P]),{a:c.best[0].toLocaleLowerCase('tr'),c:opText(c.best[1])}));
 if(c.worst)parts.push(fill(pick(CWORST8[P]),{a:c.worst[0].toLocaleLowerCase('tr'),c:opText(c.worst[1])}));
 if(c.hes)parts.push(pick(CHES8[P]));if(kn)parts.push(fill(pick(CKIA8[P]),{n:kn}));else if(c.kiaN)parts.push(fill(pick(CKIA8[P]),{n:c.kiaN+' askerimiz'}));
 if(c.sivil)parts.push(pick(CSIV8[P]));else if(c.giz>=70&&c.res>=1)parts.push(pick(CGIZ8[P]));
 if(c.fit===true&&parts.length<5)parts.push(pick(CFIT8[P]));if(c.fit===false&&c.res<2&&parts.length<5)parts.push(pick(CNOFIT8[P]));
 const keys=['sorumluluk'];if(kn||c.kiaN)keys.push('aile');if(c.res>=1&&c.mvp)keys.push('adamlar');if(c.sivil)keys.push('sivil');if(c.worst)keys.push('savun');if(c.res===2)keys.push('hirs');if(c.res===0)keys.push('egitim');keys.push('kaynak');
 const K=[...new Set(keys)].slice(0,4);
 pushModal({k:'Komutanın odası',ti:cmdr(),art:`<div class="row" style="gap:12px;padding:10px;align-items:flex-start">${cmdrFace()}<div class="speech">${parts.map(p=>`<p>${esc(p[0].toLocaleUpperCase('tr')+p.slice(1))}</p>`).join('')}</div></div>`,body:`<div class="row wrap" style="gap:6px">${c.ti?`<span class="chip">${esc(c.ti)}</span>`:''}${c.best?'<span class="chip" style="color:var(--green)">Öne çıkan karar</span>':''}${c.worst?'<span class="chip" style="color:var(--red)">Hatalı karar</span>':''}${c.hes?'<span class="chip" style="color:var(--amber)">Tereddüt</span>':''}${kn||c.kiaN?'<span class="chip" style="color:var(--red)">Şehit</span>':''}</div><p class="small muted">Komutanın kişiliği: ${esc(CMDP[P].n)}. Cevabın ilişkinizi ve yarını etkiler.</p>`,
  ch:K.map(k=>({t:fill(CREP8[k],{m:c.mvp||'Tim',n:kn?ek(kn,'nin'):'Şehidimizin'}),fn:()=>{
   const good={sorumluluk:P==='sert'||res===2||R()<.5,adamlar:res>=1&&(P!=='soguk'||res===2),aile:true,savun:S.st.strat>=45||(P==='babacan'&&R()<.5),hirs:res===2&&(P!=='babacan'||S.st.lider>45),egitim:true,kaynak:P==='soguk'?res>=1:P==='babacan',sivil:true}[k];
   const L=CRESP8[k][P];const txt=fill(good?L[0]:L[1],{m:c.mvp||'Tim'});let g=good?(k==='aile'||k==='hirs'?3:2):-2;const ef=[];
   S.trust=clamp(S.trust+g);ef.push(['Komutan güveni',g]);
   if(k==='adamlar'&&good&&S.tim){S.tim.m.forEach(m=>m.mor=clamp(m.mor+6));ef.push(['Birlik morali',6])}
   if(k==='aile'){addSt('mental',-4);addSt('hirs',2);if(S.kogus)kall(4);ef.push(['Ruh hali',-4],['Hırs',2])}
   if(k==='hirs'&&good){S.nextHard=true;ef.push(['Yarın zor görev · tecrübe ×1,25',1])}
   if(k==='egitim'){addSt('strat',1);S.fatigue=clamp(S.fatigue+8);ef.push(['Strateji',1])}
   if(k==='sivil'){S.trust=clamp(S.trust+1);addSt('disiplin',1);ef.push(['Disiplin',1])}
   if(k==='sorumluluk')addSt('lider',.6);
   setTimeout(()=>pushModal({k:'Komutanın odası',ti:'Komutanın yanıtı',art:`<div class="row" style="gap:12px;padding:10px;align-items:flex-start">${cmdrFace()}<div class="speech"><p>${esc(txt)}</p></div></div>`,body:`<div class="fx">${ef.map(([n,v])=>`<span class="${v>=0?'p':'n'}">${esc(n)}${typeof v==='number'&&n.indexOf('×')<0?' '+(v>=0?'+':'')+v:''}</span>`).join('')}</div>`}),0)}}))})}

/* ---------- HAREKÂT EKRANI ---------- */
function hud8(o){const H=[['Kuvvet',o.hp,o.hp<40?'var(--red)':'var(--green)'],['Mühimmat',o.amm,o.amm<30?'var(--red)':'var(--blue)'],['Gizlilik',o.giz,'var(--acc)'],['İnisiyatif',o.mom,o.mom<35?'var(--red)':'var(--amber)']];
 return `<div class="hud">${H.map(([n,v,c])=>`<div><span>${n}</span><b>${Math.round(v)}</b><i><em style="width:${clamp(v)}%;background:${c}"></em></i></div>`).join('')}</div>`}
function vMission(){const sub=UI.msub||'op';
 const seg=`<div class="seg"><button class="${sub==='op'?'on':''}" data-a="msub" data-v="op">Harekât</button><button class="${sub==='unit'?'on':''}" data-a="msub" data-v="unit">${esc(S.tim&&uLv()<=3?S.tim.name+' '+uName():'Birliğim')}</button><button class="${sub==='state'?'on':''}" data-a="msub" data-v="state">${S.rank>=18?'Devlet':ico('lock',12)+' Devlet'}</button></div>`;
 if(sub==='unit')return seg+medalRack()+vUnit();
 if(sub==='state'){polInit();return seg+vState()}
 if(S.izin)return seg+`<div class="card hero leave"><div class="lbl acc">İzin belgesi</div><h2 class="stencil" style="font-size:28px">Bugün izinlisin</h2><p>${(S.day-1)%7===6?'Haftalık dinlenme günü.':'Komutanının verdiği ödül iznini kullanıyorsun.'} Harekât yok. Üniformayı çıkar, şehre in, sevdiklerinle vakit geçir.</p><div class="row wrap"><button class="btn grow" data-a="goto" data-v="life" onclick="UI.life='social';UI.lifeLock=1;setTimeout(()=>UI.lifeLock=0)">Dışarı çık</button>${S.partner?`<button class="btn ghost grow" data-a="lifetab" data-v="love" onclick="UI.tab='life'">${esc(S.partner.name)} ile buluş</button>`:''}</div></div>`;
 const o=S.op;if(!o)return seg;upgradeOp();const def=OPS.find(x=>x.id===o.id);const al=alarm();const e=equipped();timSync();
 const started=!!o.prep;const cur=Math.min(o.st,(o.steps||[]).length-1||5);
 const head=`<div class="dossier"><div class="dz-top"><span>GİZLİ · ${OPHEAD[T()]}</span><span class="num">${gDate()} · ${started?clk8(o.clk):'H-01:00'}</span></div>
 ${scene(def.sc)}<div class="dz-body"><div class="stamp">${o.hard?'ÖNCELİKLİ':'GİZLİ'}</div><div class="lbl acc">Harekât ${esc(o.code||'')}</div><h2 class="stencil" style="font-size:26px;line-height:1.02">${esc(def.ti)}</h2>
 <div class="saha s-${o.saha||'yurtici'}"><b>${SAHA[o.saha||'yurtici'][0]}</b><span>${flag(o.cn||S.nation,14)} ${esc(NAT[o.cn||S.nation].n)}</span>${o.chain?`<em>ZİNCİR · ${esc(o.chain)}</em>`:''}</div>
 <div class="meta"><div><span>Birlik</span><b>${esc(unitTitle())} · ${USZ8[uLv()].toLocaleString('tr-TR')}</b></div><div><span>Bölge</span><b>${ico('pin',12)} ${esc(o.city[0])}</b></div><div><span>Karşı taraf</span><b>${flag(o.en,16)} ${esc(NAT[o.en].n)}</b></div><div><span>${o.al?'Müttefik':'Alarm'}</span><b>${o.al?flag(o.al,16)+' '+esc(NAT[o.al].n):`<span style="color:${al[2]}">${al[1]}</span>`}</b></div><div><span>Hava</span><b>${S.wx?esc(S.wx.i+' '+S.wx.n+' · '+S.wx.t+'°'):'—'}</b></div><div><span>Silahın</span><b>${esc(e.p?e.p.n:'—')}</b></div></div>
 ${started?tacMap(o,def):'<div class="mapwrap">'+opMap()+'</div>'}
 <div class="opbar">${(o.steps||[0,1,2,3,4,5]).map((_,i)=>`<i class="${S.mDone||i<o.st?'ok':started&&i===o.st?'now':''}"></i>`).join('')}</div><div class="oplbl"><span>${started?S.mDone?'Harekât tamamlandı':`Aşama ${cur+1}/${(o.steps||[]).length||6} · ${stepLabel(o,cur)}`:'Hazırlık'}</span><span>${started?'Rol: '+urole(uLv()):''}</span></div>
 ${started?hud8(o):''}${!S.mDone?prepChips(o):''}</div></div>`;
 const radio=o.logs&&o.logs.length?`<div class="card radio"><div class="sec-h"><h2>Telsiz</h2><span class="chip live">● CANLI</span></div>${o.logs.slice().reverse().map((l,i)=>`<div class="rl ${l.k} ${i===0&&!S.mDone?'new':''}"><span class="tm">${l.c}</span><div><b>${esc(l.w)}:</b> ${esc(l.t)}${l.d?`<div class="dl">${l.d.hp?`<em class="${l.d.hp<0?'n':'p'}">Kuvvet ${l.d.hp}</em>`:''}${l.d.mom?`<em class="${l.d.mom<0?'n':'p'}">İnisiyatif ${l.d.mom>0?'+':''}${l.d.mom}</em>`:''}${l.d.giz?`<em class="${l.d.giz<0?'n':'p'}">Gizlilik ${l.d.giz>0?'+':''}${l.d.giz}</em>`:''}</div>`:''}</div></div>`).join('')}</div>`:'';
 if(S.mDone){const r=S.mRes||{};return seg+head+`<div class="card"><div class="lbl">Bugünkü harekât tamamlandı</div><h2 class="stencil" style="font-size:22px">${['Başarısız','Kısmi başarı','Görev başarılı'][r.res??1]}</h2><div class="fx"><span class="p">Tecrübe +${r.xp||0}</span><span class="${(r.trs||0)>=0?'p':'n'}">Güven ${(r.trs||0)>=0?'+':''}${r.trs||0}</span></div><p class="small muted">Yarın sabah yeni harekât emri gelecek. Bu arada birliğinle ilgilen, antrenman yap ya da dinlen.</p><button class="btn ghost block" data-a="msub" data-v="unit">Birliğine git</button></div>`+radio}
 if(!o.prep){const I=o.intel||intelOf(o);return seg+head+`<div class="card"><div class="sec-h"><h2>İstihbarat brifingi</h2><span class="chip" style="color:var(--acc)">${S.wx?esc(S.wx.i+' '+S.wx.n):''}</span></div>
 <div class="aar"><div><span>Tahmini düşman</span><b>~${I.en.toLocaleString('tr-TR')} personel</b></div><div><span>Zırhlı araç</span><b>${I.veh||'Yok'}</b></div><div><span>Kendi kuvvetin</span><b>${USZ8[uLv()].toLocaleString('tr-TR')} personel</b></div><div><span>Arazi</span><b>${esc(I.terr)}</b></div><div><span>Birlik hazırlığı</span><b>%${timReady()}</b></div><div><span>Görev süresi</span><b>6 aşama</b></div></div>${o.mod&&MOD8[o.mod]?`<div class="brief crit"><span class="n">!</span><div><b>Özel durum: ${esc(MOD8[o.mod].n)}</b><span class="small">${esc(MOD8[o.mod].d)}</span></div></div>`:''}${o.hard?'<p class="small red">Komutanın sana zor bir görev verdi: düşman %40 daha güçlü, tecrübe ×1,25.</p>':''}</div>
 ${prepPanel(o)}`}
 const[sit,opts]=stepData(o,o.st,def);const stp=o.steps[o.st];const timed=!!stp.tm;let tm='';
 if(timed){const key=S.day+'-'+o.st;if(!UI.kt||UI.kt.k!==key)UI.kt={k:key,end:Date.now()+KT_MS};const rem=Math.max(0,UI.kt.end-Date.now());clearTimeout(UI.ktT);clearInterval(UI.ktI);
  UI.ktT=setTimeout(()=>{if(UI.kt&&UI.kt.k===key&&S.op&&S.op.st===KTI&&!S.mDone&&!MO&&UI.tab==='mission'&&(UI.msub||'op')==='op'&&!UI.ktPause&&!ADON)opStep('to');else UI.kt=null},rem);
  UI.ktI=setInterval(()=>{const el=document.getElementById('ktn');if(!el){clearInterval(UI.ktI);return}const r=Math.max(0,Math.ceil((UI.kt?UI.kt.end-Date.now():0)/1000));el.textContent=r+' sn'},250);
  tm=`<div class="ktw"><span class="lbl red">Karar süresi</span><b id="ktn" class="num">${Math.ceil(rem/1000)} sn</b></div><div class="kt"><i style="--w:${rem/KT_MS*100}%;animation-duration:${rem}ms"></i></div>${rwBtn('time','Kritik an +15 saniye','rwtime','time')}`}
 const optsH=ordsOf(o,opts).map((idx,j)=>{const op=opts[idx];if(!op)return'';return`<button class="opt op2 evo" data-a="opick" data-v="${idx}"><span class="k">${'ABCDE'[j]}</span><span class="grow">${op[4]?`<span class="auth">${ico('shield',11)} ${esc(op[4])}</span>`:''}<span class="evt">${esc(opText(op[0]))}</span>${o.rev===o.st&&idx===opts.reduce((b,x,i)=>x[1]>opts[b][1]?i:b,0)?'<span class="intel23">🛰 İstihbarat: en doğru emir</span>':''}<span class="evm">${tagChip(op[3])}<span class="tag">${STATN[op[2]]} ${Math.round(S.st[op[2]])}</span></span></span></button>`}).join('');
 const n=(o.steps||[]).length||6;const fresh=UI.evKey!==S.day+'-'+o.st;if(fresh){UI.evKey=S.day+'-'+o.st;setTimeout(()=>{const e=document.getElementById('evc');const sc=document.getElementById('scr')||document.querySelector('.scr');if(e&&sc){const r=e.getBoundingClientRect(),rs=sc.getBoundingClientRect();sc.scrollTo({top:sc.scrollTop+r.top-rs.top-32,behavior:'smooth'})}},60)}
 return seg+head+`<section id="evc" class="evc ${timed?'crit':''} ${fresh?'fresh':''}">
 <div class="evc-bar"><span class="evc-live"><i></i>${timed?'ACİL KARAR':'CANLI GELİŞME'}</span><span class="evc-st">Aşama ${o.st+1}/${n}</span></div>
 <div class="evc-body"><div class="evc-k">${esc(stepLabel(o,o.st))}</div><p class="evc-t">${esc(opText(sit))}</p>${o.nb?`<div class="evc-nb">Komuta yeteneği aktif: bu adımda şans +%${Math.round(o.nb*100)}</div>`:''}${tm}</div>
 <div class="evc-q"><span>Emrin nedir?</span><small>${opts.length} seçenek · birini seç</small></div>
 <div class="evc-opts">${optsH}</div>
 <p class="evc-f">${timed?'Süre dolarsa birliğin tereddüt eder ve en kötü sonuç gerçekleşir.':'Kararın; yeteneklerine, yorgunluğuna, ruh haline, silahına ve birliğinin hazırlığına göre icra edilir.'}</p></section>
 ${cmdStrip(o)}${abilRow(o)}${radio}`}

/* ---------- BİRLİĞİM ---------- */
function unitEmblem(sz=86){const a=getAcc();const nm=S.tim?S.tim.name:'';return `<svg viewBox="0 0 100 116" width="${sz}" aria-hidden="true"><defs><linearGradient id="ueg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3a3d36"/><stop offset="1" stop-color="#121410"/></linearGradient></defs><path d="M50 4 L94 18 L90 70 Q84 98 50 112 Q16 98 10 70 L6 18Z" fill="url(#ueg)" stroke="${a}" stroke-width="3"/><path d="M50 12 L86 23 L82 68 Q77 92 50 104 Q23 92 18 68 L14 23Z" fill="none" stroke="#ffffff22"/><text x="50" y="58" text-anchor="middle" font-family="Oswald,Arial Narrow,sans-serif" font-weight="700" font-size="30" fill="${a}">${esc((uLv()>=10?unitTitle().split(' ').filter(w=>w.length>2).slice(0,2).map(w=>w[0]).join(''):nm.slice(0,2)).toLocaleUpperCase('tr'))}</text>${(()=>{const et=emblemText();const long=et.length>10;return `<text x="50" y="80" text-anchor="middle" font-family="Oswald,Arial Narrow,sans-serif" font-size="${long?7.5:9}" letter-spacing="2" fill="#ddd" ${long?'textLength="64" lengthAdjust="spacingAndGlyphs"':''}>${esc(et)}</text>`})()}<path d="M30 90 H70" stroke="${a}" stroke-width="2"/></svg>`}
function vUnit(){timSync();const U=S.tim,lv=uLv();const M=U.m;const rd=timReady();
 return `<div class="card hero"><div class="row" style="gap:14px">${unitEmblem()}<div class="grow"><div class="lbl acc">${esc(urole(lv))}</div><h2 class="uttl">${esc(unitTitle(lv))}</h2><div class="small muted">${USZ8[lv].toLocaleString('tr-TR')} personel${unitTitle(lv).includes(B().n.split('·').pop().trim())?'':' · '+esc(B().n.split('·').pop().trim())}</div></div></div>
 ${bar('Hazırlık',rd,rd<45?'var(--red)':'var(--green)')}<div class="aar"><div><span>Harekât</span><b>${U.ops}</b></div><div><span>Başarılı</span><b>${U.win}</b></div><div><span>Şehit</span><b class="${U.fallen.length?'red':''}">${U.fallen.length}</b></div><div><span>Yaralı (şu an)</span><b>${M.filter(m=>m.w).length}</b></div></div>
 <div class="tiles"><button class="tile" data-a="unit" data-v="tatbikat" ${S.unitD===S.day+'t'?'disabled':''}><b>${ico('target',16)} Birlik tatbikatı</b><small>1 eylem · Tecrübe +6 · Liderlik</small></button><button class="tile" data-a="unit" data-v="moral" ${S.unitD===S.day+'m'?'disabled':''}><b>${ico('people',16)} Moral toplantısı</b><small>1 eylem · Moral +8</small></button></div></div>
 <div class="sec-t">${lv<=1?'Tim arkadaşların':lv<=3?'Timlerin ve kilit personel':'Kilit personel ve alt komutanlar'}</div>
 <div style="display:flex;flex-direction:column;gap:8px">${M.map((m,i)=>`<div class="card" style="padding:11px"><div class="row">${avatar(58,B(),Math.max(0,Math.min(17,S.rank-(lv>=4?1:2))),m.look,S.nation,m.n)}<div class="grow"><b style="font:700 16px var(--font-c)">${esc(m.n)}</b> ${m.w?`<span class="chip" style="color:var(--red)">Yaralı · ${m.w} gün</span>`:''}<div class="small muted">${esc(m.r)} · ${'★'.repeat(1+Math.floor(m.xp/25))}<span style="opacity:.3">${'★'.repeat(4-Math.floor(m.xp/25))}</span> · ${S.day-m.since>0?(S.day-m.since)+' gündür seninle':'yeni katıldı'}</div><div class="bar" style="grid-template-columns:44px 1fr 30px"><span class="small">Moral</span><div class="t"><i style="width:${m.mor}%;background:${m.mor<40?'var(--red)':'var(--green)'}"></i></div><span class="v">${Math.round(m.mor)}</span></div></div><button class="mini b" data-a="unit" data-v="gor|${i}">Görüş</button></div></div>`).join('')}</div>
 ${U.fallen.length?`<div class="card"><div class="sec-h"><h2>Şehitlik</h2></div>${U.fallen.map(f=>`<div class="row small" style="gap:8px;border-bottom:1px solid var(--line);padding:6px 0"><span class="red">✝</span><div class="grow"><b>${esc(f.n)}</b> · ${esc(f.r)}<br><span class="muted">Gün ${f.d} · ${esc(f.op)}</span></div></div>`).join('')}</div>`:''}
 <div class="card"><div class="sec-h"><h2>Komuta yolu</h2></div><div class="upath">${UL8[uKind()].map((n,i)=>`<div class="${i<lv?'ok':i===lv?'now':''}"><b>${esc(n)}</b><small>${USZ8[i].toLocaleString('tr-TR')}</small></div>`).join('')}</div><p class="small muted">Rütben yükseldikçe birliğin büyür. Eski tim arkadaşların seninle yükselir ve yeni görevler alır.</p></div>`}
const GOR8=[['Ailesini sor','"Annem her gün arıyor. Ona seni anlattım, seni merak ediyor."',8],['Korkularını konuş','"Gece gözümü kapatınca son harekâtı görüyorum. Kimseye söylemedim."',10],['Gelecek planlarını sor','"Bu iş bitince bir çiftlik almak istiyorum. Belki sen de gelirsin, ha?"',7],['Performansını değerlendir','"Haklısın komutanım. Atış ortalamamı düzelteceğim."',6]];
function unitAct(v){const[a,i]=v.split('|');timSync();const M=S.tim.m;
 if(a==='tatbikat'){if(S.unitD===S.day+'t')return;if(!useAP())return;S.unitD=S.day+'t';M.forEach(m=>{m.xp=Math.min(100,m.xp+6);m.mor=clamp(m.mor-2)});addSt('lider',1);S.fatigue=clamp(S.fatigue+8);toast(pick(['Gece tatbikatı tamam: baskın, tahliye ve yaralı taşıma prova edildi.','Canlı atışlı tatbikatta birliğin tempoyu yakaladı.','Muhabere ve harita tatbikatı: herkes kendi rolünü ezbere biliyor.'])+' Tecrübe +6')}
 if(a==='moral'){if(S.unitD===S.day+'m')return;if(!useAP())return;S.unitD=S.day+'m';M.forEach(m=>m.mor=clamp(m.mor+8));addSt('lider',.5);toast(pick(['Herkesi topladın, açık konuştun. Omuzlar dikleşti.','Kantinde birlikte yemek yediniz; şakalar geri geldi.','Şehitlerimizi andınız ve geleceği konuştunuz.'])+' Moral +8')}
 if(a==='gor'){const m=M[+i];if(!m)return;pushModal({k:esc(uName())+' · Birebir görüşme',ti:m.n,art:`<div class="row" style="justify-content:center;padding:8px">${avatar(84,B(),Math.max(0,S.rank-2),m.look,S.nation,m.n)}</div>`,body:`<p class="small muted">${esc(m.r)} · Moral ${Math.round(m.mor)}</p><p>Neyi konuşmak istersin? (1 eylem)</p>`,ch:GOR8.map(([t,l,g])=>({t,fn:()=>{if(!useAP())return;m.mor=clamp(m.mor+g);if(t.startsWith('Perf')){m.xp=Math.min(100,m.xp+4)}addSt('lider',.4);setTimeout(()=>pushModal({k:'Birebir görüşme',ti:m.n.split(' ')[0],body:`<p>${esc(l)}</p><div class="fx"><span class="p">Moral +${g}</span></div>`}),0)}})).concat([{t:'Vazgeç',fn:()=>{}}])})}
 save();render()}

/* ---------- KOĞUŞ: etkinlikler, planlar, sohbet ---------- */
const KGAME8={TR:'okey ve tavla',ABD:'poker',RUS:'satranç ve durak',CIN:'mahjong ve xiangqi',ALM:'Skat',IGB:'dart',FRA:'belote',JPN:'shogi ve mahjong',PAK:'carrom',ITA:'scopa',SUR:'tavla',UZB:'satranç ve tavla',AZE:'nərd (tavla)',ISR:'shesh besh (tavla)'};
const KMAC8={TR:'lig derbisi',ABD:'Amerikan futbolu maçı',RUS:'hokey maçı',CIN:'basketbol finali',ALM:'lig derbisi',IGB:'futbol maçı',FRA:'lig klasiği',JPN:'beyzbol maçı',PAK:'kriket maçı',ITA:'lig derbisi',SUR:'milli takım maçı',UZB:'milli takım maçı',AZE:'lig maçı',ISR:'lig maçı'};
function kogusAct(v){const[a,i]=v.split('|');const K=S.kogus||[];S.kd=S.kd||{};
 if(a==='cay'){if(S.money<250)return toast('Paran yetmiyor.');if(S.soc.cay===S.day)return toast('Bugün zaten ısmarladın.');S.money-=250;S.soc.cay=S.day;kall(4);S.kh=clamp(S.kh+5);toast('Kantinden çay ve simit geldi. Koğuşun havası ısındı.')}
 if(a==='konus'){const m=K[+i];if(!m)return;const op={kavgaci:'"Ne var? …Tamam, otur. Bugün sinirlerim bozuk."',sakaci:'"Komutanım geldi, herkes hazır ol! Şaka şaka, otur."',sessiz:'"…Merhaba. Otur istersen."',kidemli:'"Gel bakalım acemi… pardon, artık acemi değilsin."',yetenekli:'"Tam da seninle konuşmak istiyordum."',kurnaz:'"Senin için bir haberim var ama önce sen anlat."'}[m.t];
  pushModal({k:kname()+' · Sohbet',ti:m.n,art:`<div class="row" style="justify-content:center;padding:8px">${avatar(84,B(),Math.max(0,S.rank-2),m.look,S.nation,m.n)}</div>`,body:`<p>${esc(op||'"Gel otur."')}</p><p class="small muted">${TRAITS[m.t]} · Bağ ${Math.round(m.b)} · Sohbet 1 eylem</p>`,ch:[
   ['Ailesini ve memleketini sor',()=>{kb(+i,10);addSt('mental',2);return pick(['Fotoğraf çıkardı: küçük kız kardeşi. "Bitince onu okula ben götüreceğim."','Köyünü anlattı; dağları, babasının bahçesini. Sesi yumuşadı.','"Annem bana her hafta kurabiye yolluyor. Sana da ayırırım."'])}],
   ['Dertleş, kendi hikâyeni anlat',()=>{kb(+i,14);addSt('mental',4);return pick(['Uzun süre sustu. Sonra "Hiç bilmiyordum," dedi. Aranızda bir şey değişti.','"Sen de mi?" dedi. Aynı yükü taşıyan iki insan gibi baktınız birbirinize.'])}],
   ['Bir plan yap: izinde birlikte şehre inin',()=>{kb(+i,8);S.kplan={t:'sehir',by:m.n};return'"Anlaştık! Ben bir yer biliyorum; yemekler efsane." İlk izin gününde planınız hazır.'}],
   ['Şakalaş, havayı yumuşat',()=>{kb(+i,m.t==='sakaci'?14:6);S.kh=clamp(S.kh+2);return m.t==='kavgaci'?'Önce kaşlarını çattı, sonra kahkahayı bastı.':'Koğuş kahkahalarla inledi.'}]].map(([t,f])=>({t,fn:()=>{if(!useAP())return;const r=f();log(m.n+' ile sohbet.');setTimeout(()=>pushModal({k:'Sohbet',ti:m.n.split(' ')[0],body:`<p>${esc(r)}</p>`}),0)}})).concat([{t:'Sonra konuşuruz',fn:()=>{}}])});return}
 if(a==='oyun'||a==='mac'||a==='film'||a==='spor'){if(S.kd[a]===S.day)return toast('Bunu bugün zaten yaptınız.');if(!useAP())return;S.kd[a]=S.day;
  if(a==='oyun'){const g=KGAME8[S.nation]||'kart';pushModal({k:kname()+' · Oyun gecesi',ti:g[0].toLocaleUpperCase('tr')+g.slice(1)+' turnuvası',art:scene('kisla'),body:`<p>Ranzalar kenara çekildi, ortaya bir masa kuruldu. ${esc(pick(K).n)} kuralları üçüncü kez anlatıyor; ${esc(pick(K).n)} şimdiden hile yapıldığını iddia ediyor.</p>`,ch:[
   {t:'Ciddi oyna, kazanmak için',fn:()=>{const w=R()<.35+S.st.strat/200;kall(w?2:4);S.kh=clamp(S.kh+4);addSt('strat',.5);if(w){S.money+=200;toast('Turnuvayı kazandın! Ödül: herkesin çay parası (+200). Ama rövanş istiyorlar.')}else toast('Finalde kaybettin. Koğuş "Komutan da insanmış" diye güldü.')}},
   {t:'Keyfine oyna, ortamı neşelendir',fn:()=>{kall(5);S.kh=clamp(S.kh+6);addSt('mental',4);toast('Kimse kazananı hatırlamıyor; herkes gülmekten yoruldu. Ruh hali +4')}}]})}
  if(a==='mac'){const mc=KMAC8[S.nation]||'maç';const sk=R();pushModal({k:kname()+' · Maç gecesi',ti:'Hep birlikte '+mc,art:scene('kisla'),body:`<p>Kantindeki televizyonun önüne sandalyeler dizildi. Çekirdekler, çaylar hazır. ${esc(pick(K).n)} formasını giymiş, ${esc(pick(K).n)} karşı takımı tutuyor; ortam şimdiden gergin.</p>`,ch:[
   {t:'Bir takımı tut ve küçük bir iddiaya gir',fn:()=>{if(sk<.5){S.money+=150;kall(3);S.kh=clamp(S.kh+6);addSt('mental',5);toast('Son dakika golü! Koğuş yıkıldı, iddiayı sen kazandın (+150).')}else{S.money-=150;kall(3);S.kh=clamp(S.kh+3);addSt('mental',2);toast('Penaltılarda kaybettiniz. İddia parası gitti (−150) ama gece unutulmazdı.')}}},
   {t:'Tarafsız kal, ortamı yatıştır',fn:()=>{kall(4);S.kh=clamp(S.kh+5);addSt('lider',.5);addSt('mental',3);toast(sk<.5?'Maç berabere bitti; kimse kavga etmedi, bu senin sayende.':'Gerilen iki kişiyi araya girip güldürdün. Gece tatlı bitti.')}}]})}
  if(a==='film'){kall(3);S.kh=clamp(S.kh+4);addSt('mental',4);toast(pick(['Eski bir savaş filmi izlediniz; sonunda herkes sessizce dağıldı.','Komedi gecesi: koğuş saatlerce aynı replikleri tekrarladı.','Bir belgesel izlediniz; sonrasında saatlerce taktik tartıştınız.'])+' Ruh hali +4')}
  if(a==='spor'){kall(3);addSt('guc',.8);addSt('dayan',.6);S.fatigue=clamp(S.fatigue+10);S.kh=clamp(S.kh+3);toast('Koğuşça spor salonu: barfiks yarışında herkes birbirini gazladı. Güç +0,8')}}
 save();render()}
const KPLAN8=[
 {ti:'Şehre inme planı',tx:a=>`${a}: "Bu Pazar izinde hep birlikte şehre inelim. Bir yer biliyorum; yemekleri efsane, sahibi de eski asker."`,ch:[['Varım, ben de birini davet ederim',a=>{S.kplan={t:'sehir',by:a};kall(3);return'Plan yapıldı. İlk izin gününde "Koğuşla şehre in" seçeneği açılacak.'}],['Bu hafta olmaz',a=>{kall(-1);return'Biraz bozuldular ama anlayış gösterdiler.'}]]},
 {ti:'Bölükler arası halı saha',tx:a=>`${a}: "Yan bölükle maç ayarladım. Kaybeden bütün haftanın çayını ısmarlayacak. Kaptan sen ol!"`,ch:[['Kaptanlığı al',a=>{const w=R()<.35+(S.st.dayan+S.st.lider)/300;S.fatigue=clamp(S.fatigue+10);if(w){kall(6);S.kh=clamp(S.kh+8);addSt('lider',1);return'4-3 kazandınız! Son golü senin pasınla attılar. Koğuş seni omuzlarında taşıdı.'}S.money-=200;kall(3);S.kh=clamp(S.kh+3);return'2-3 kaybettiniz. Çay parası senden (−200) ama herkes iyi oynadığınızı söylüyor.'}],['Sadece oyuncu ol',a=>{kall(3);S.kh=clamp(S.kh+3);addSt('dayan',.6);return'Kenar bekçisi gibi koştun; maç keyifliydi.'}],['Katılma',a=>{kall(-2);return'Tribünde kaldın; biraz dışlanmış hissettin.'}]]},
 {ti:'Gece mutfak baskını',tx:a=>`${a}, gece 02:00'de mutfaktan börek "kurtarma" harekâtı planlıyor. "Nöbetçi benim dayının oğlu, sorun yok," diyor.`,ch:[['Katıl',a=>{if(R()<.45){S.trust=clamp(S.trust-4);kall(5);S.kh=clamp(S.kh+4);return'Yakalandınız! Sabaha kadar bulaşık yıkadınız. Güven −4 ama koğuşta efsane oldunuz.'}kall(6);addSt('mental',4);S.kh=clamp(S.kh+6);return'Görev başarılı. Gece yarısı ranzalarda börek ziyafeti!'}],['Vazgeçirmeye çalış',a=>{addSt('disiplin',1);kall(-1);return'"Sen de amma komutansın," dediler ama vazgeçtiler.'}],['Komutana bildir',a=>{S.trust=clamp(S.trust+2);kall(-8);S.kh=clamp(S.kh-6);return'Plan iptal oldu. Koğuşta sana soğuk bakıyorlar.'}]]},
 {ti:'Hastaneden dönüş',tx:a=>`${a}: "Yarın revirden çıkan arkadaşımız dönüyor. Ona küçük bir karşılama hazırlayalım mı?"`,ch:[['Organize et, masrafı sen karşıla',a=>{S.money-=200;kall(6);S.kh=clamp(S.kh+7);addSt('mental',4);return'Kapıda pankart, içeride pasta. Gözleri doldu. Koğuş hiç bu kadar yakın olmamıştı.'}],['Katıl ama organize etme',a=>{kall(2);S.kh=clamp(S.kh+2);return'Güzel bir karşılama oldu.'}]]},
 {ti:'Ortak çalışma grubu',tx:a=>`${a}: "Kurs sınavı yaklaşıyor. Akşamları birlikte çalışalım; sen harita okumayı iyi biliyorsun."`,ch:[['Grubu sen yönet',a=>{addSt('strat',1);addSt('lider',.8);kall(4);S.fatigue=clamp(S.fatigue+6);return'Üç akşam boyunca harita, telsiz usulü ve taktik çalıştınız. Herkes sana teşekkür etti.'}],['Katıl ama yönetme',a=>{addSt('strat',.6);kall(2);return'Birlikte çalışmak iyi geldi.'}],['Vaktim yok',a=>{kall(-2);return'Kendi başlarına çalıştılar.'}]]},
 {ti:'Gitar gecesi',tx:a=>`${a} bir gitar buldu. "Bu gece koğuşta türkü/şarkı gecesi var, sen de bir tane söyleyeceksin!"`,ch:[['Sahneye çık, sen de söyle',a=>{addSt('mental',6);kall(5);S.kh=clamp(S.kh+6);return'Sesin pek iyi değildi ama herkes eşlik etti. Bu gece kimse savaşı düşünmedi.'}],['Sadece dinle',a=>{addSt('mental',3);kall(2);return'Gözlerini kapatıp dinledin. İyi geldi.'}]]},
 {ti:'Bebek haberi',tx:a=>`${ek(a,'nin')} bebeği oldu! Koğuş ona ortak bir hediye almak için para topluyor.`,ch:[['Cömert davran',a=>{S.money-=250;kall(5);S.kh=clamp(S.kh+5);return'Hediyeyi sen seçtin: küçük bir asker tulumu. Arkadaşın ağladı.'}],['Az da olsa katıl',a=>{S.money-=80;kall(2);return'Hediye gönderildi; fotoğrafını koğuşun duvarına astılar.'}]]}];
function kplanEvent(){const K=S.kogus;if(!K||!K.length)return;const ev=pick(KPLAN8.filter(e=>!(S.kps||[]).includes(e.ti)))||pick(KPLAN8);S.kps=[...(S.kps||[]),ev.ti].slice(-4);const m=pick(K);
 pushModal({k:kname()+' · Bir plan var',ti:ev.ti,art:`<div class="row" style="justify-content:center;padding:8px">${avatar(72,B(),Math.max(0,S.rank-2),m.look,S.nation,m.n)}</div>`,body:`<p>${esc(ev.tx(m.n))}</p>`,ch:ev.ch.map(([t,f])=>({t,fn:()=>{const r=f(m.n);log(kname()+': '+ev.ti);setTimeout(()=>pushModal({k:kname(),ti:ev.ti,body:`<p>${esc(r)}</p>`}),0)}}))})}
function kogusTick(){if(!S.kogus)return;const avg=S.kogus.reduce((a,m)=>a+m.b,0)/S.kogus.length;S.kh=clamp((S.kh??55)*.85+avg*.15);addSt('mental',(S.kh-50)/40);const r=R();if(r<.3)kogusEvent();else if(r<.55)kplanEvent()}
function lifeKogus(){const K=S.kogus||[];const g=KGAME8[S.nation]||'kart',mc=KMAC8[S.nation]||'maç';S.kd=S.kd||{};
 const acts=[['oyun',g[0].toLocaleUpperCase('tr')+g.slice(1)+' turnuvası','Strateji · Bağ +'],['mac','Hep birlikte '+mc,'Ruh hali · Bağ +'],['film','Film gecesi','Ruh hali +4'],['spor','Koğuşça spor salonu','Güç · Dayanıklılık']];
 return `<div class="card hero"><div class="sec-h"><h2>${kname()}</h2><span class="chip" style="color:${S.kh>65?'var(--green)':S.kh<40?'var(--red)':'var(--amber)'}">${S.kh>65?'Kenetlenmiş':S.kh<40?'Gergin':'Normal'}</span></div>${bar('Koğuş havası',S.kh,S.kh<40?'var(--red)':'var(--green)')}<p class="small muted">Koğuşun havası ruh halini her gün etkiler; 70'in üstünde harekâtlarda da avantaj sağlar. Arkadaşların bazen plan yapar, bazen kavga eder; nasıl davrandığını herkes görür.</p><button class="btn ghost block" data-a="kog" data-v="cay|0" ${S.soc.cay===S.day||S.money<250?'disabled':''}>Koğuşa çay ve simit ısmarla (${money(250)})</button></div>
 <div class="sec-t">Koğuş etkinlikleri · 1 eylem</div><div class="tiles">${acts.map(([k,n,d])=>`<button class="tile" data-a="kog" data-v="${k}|0" ${S.kd[k]===S.day?'disabled':''}><b>${esc(n)}</b><small>${d}</small></button>`).join('')}</div>
 ${S.kplan?`<div class="brief"><span class="n acc">✓</span><div><b>Planınız var</b><span class="small">${esc(S.kplan.by)} ile izin gününde şehre ineceksiniz.</span></div></div>`:''}
 <div style="display:flex;flex-direction:column;gap:8px">${K.map((m,i)=>`<div class="card" style="padding:11px"><div class="row">${avatar(58,B(),Math.max(0,S.rank-2),m.look,S.nation,m.n)}<div class="grow"><b style="font:700 16px var(--font-c)">${esc(m.n)}</b><div class="small muted">${TRAITS[m.t]} · ${m.b>70?'Yakın dost':m.b>45?'İyi geçiniyorsunuz':m.b>25?'Mesafeli':'Gergin'}</div><div class="bar" style="grid-template-columns:44px 1fr 30px"><span class="small">Bağ</span><div class="t"><i style="width:${m.b}%;background:${m.b<30?'var(--red)':'var(--blue)'}"></i></div><span class="v">${Math.round(m.b)}</span></div></div><button class="mini b" data-a="kog" data-v="konus|${i}">Konuş</button></div></div>`).join('')}</div>`}

