function eatOut(i){if(!S.izin)return toast('Şehirde yemek için izin günü gerekiyor.');const L=CITYF[S.nation]||CITYF.TR;const f=L[+i];if(!f)return;S.eat=S.eat||{};if(S.eat[i]===S.day)return toast('Bugün zaten oradaydın.');const n=Object.values(S.eat).filter(d=>d===S.day).length;if(n>=3)return toast('Bugün yeterince yedin; bir de yürüyüş yap.');if(S.money<f[2])return toast('Paran yetmiyor.');
 S.eat[i]=S.day;S.money-=f[2];addSt('mental',f[3]);S.nutri=clamp(S.nutri+f[4]);S.fatigue=clamp(S.fatigue-3);log(f[0]+'.');toast(f[1]+' Ruh hali +'+f[3]);if(R()<.3)setTimeout(meet,200);save();render()}
const HOB8=['tırmanış','fotoğrafçılık','gitar','koşu','satranç','resim','yemek yapmak','kitap kulübü','dalış','eski filmler'];
const MEETX8=['Kuyrukta önündeki kişi, üniformandaki birlik armasını sordu.','Yan masadan biri gülümseyerek kitabının adını sordu.','Kalabalıkta biri kahvesini üstüne döktü; özür üstüne özür diledi.','Tribünde yanındaki kişi aynı takımı tutuyordu; gol olunca sarıldınız.','Patikada yolunu kaybeden birine yol gösterdin.','Etkinlikte aynı soruya aynı anda güldünüz.'];
function meet(){const n=socialName(),job=pick(JOBS),hob=pick(HOB8),age=22+Math.floor(R()*12);const canLove=!S.partner&&!(S.trauma==='esi'&&(S.heal<10||S.day<30));const op=pick(['"Asker olmak nasıl bir şey? Gerçekten merak ediyorum."','"Bu şehirde ilk kez biriyle bu kadar rahat konuştum."','"Bir daha görüşürüz herhalde, değil mi?"','"Hafta sonları ne yaparsın?"']);
 const ch=[{t:'Numaralaşın, arkadaş olarak görüşelim',fn:()=>{S.friends=[...(S.friends||[]),{n,job,b:38,last:S.day}].slice(-8);log(n+' ile arkadaş oldunuz.');toast(n+' artık arkadaşın.')}}];
 if(canLove)ch.push({t:'İlgini belli et, akşam yemeğine davet et',fn:()=>{const p=.45+S.st.mental/250+(S.st.guc+S.st.dayan)/1000;if(R()<p){S.partner={name:n,aff:34,m:false,last:S.day};log(n+' ile flört başladı.');setTimeout(()=>pushModal({k:'Yeni biri',ti:n,body:`<p>"Olur, neden olmasın?" dedi gülümseyerek. Bir hikâye başlıyor.</p><div class="fx"><span class="p">Yeni ilişki</span></div>`}),0)}else{S.friends=[...(S.friends||[]),{n,job,b:30,last:S.day}].slice(-8);setTimeout(()=>pushModal({k:'Yeni biri',ti:n,body:'<p>"Seni çok sevdim ama şimdilik arkadaş kalalım mı?" Kibar bir ret, ama kapı kapanmadı.</p>'}),0)}}});
 ch.push({t:'Güzel bir sohbetti; vedalaş',fn:()=>{addSt('mental',2)}});
 pushModal({k:'Yeni biri',ti:n,body:`<p>${esc(pick(MEETX8))}</p><p class="small muted">${age} yaşında · ${esc(job)} · ${esc(hob)} seviyor</p><p>${esc(op)}</p><p class="small muted">Bu tanışmanın nereye gideceğine sen karar ver.</p>`,ch})}
function sehirPlan(){if(!S.kplan||!S.izin)return;if(!useAP())return;const by=S.kplan.by;S.kplan=null;mealOut('Koğuşla şehirde akşam yemeği','a');addSt('mental',10);kall(6);S.kh=clamp(S.kh+8);S.money-=250;S.fatigue=clamp(S.fatigue-8);log('Koğuşla şehre indiniz.');
 pushModal({k:'İzin günü',ti:'Koğuşla şehirde',art:scene('sehir'),body:`<p>${esc(by)} sözünü tuttu: küçük ama dolu bir lokanta, masada sıcak yemekler, sahibi eski bir astsubay. Akşam sahilde yürüdünüz, birbirinizin fotoğraflarını çektiniz. Kimse rütbe sormadı.</p><div class="fx"><span class="p">Ruh hali +10</span><span class="p">Koğuş bağı +6</span></div>`});if(R()<.5)setTimeout(meet,300);save();render()}
function lifeSocial(){
 fixFriends();const fr=S.friends||[];const CF=CITYF[S.nation]||CITYF.TR;S.eat=S.eat||{};
 const out=S.izin?`<div class="card hero"><div class="sec-h"><h2>Dış dünya</h2><span class="chip" style="color:var(--green)">İzinlisin</span></div><p class="small muted">Üniformasız bir gün. Her etkinlik 1 eylem harcar; çoğunda yeni insanlarla tanışabilirsin. İlişkinin yönüne sen karar verirsin.</p>
 ${S.kplan?`<button class="btn block" data-a="sehir">${ico('people',16)} Koğuşla şehre in (${esc(S.kplan.by)} ile plan)</button>`:''}
 <div class="tiles">${Object.entries(OUTA).map(([id,[n,e,c,m,d]])=>`<button class="tile" data-a="out" data-v="${id}" ${(S.outDone||{})[id]===S.day||S.money<c?'disabled':''}><b>${id==='aile'&&S.trauma==='aile'?'Akrabanı ziyaret et':n}</b><small>${Object.entries(e).map(([k,v])=>STATN[k]+' +'+v).join(' · ')}${c?' · '+money(c):''}</small>${m?`<small class="acc">Tanışma şansı %${Math.round(m*100)}</small>`:''}</button>`).join('')}</div></div>
 <div class="card"><div class="sec-h"><h2>Şehirde yeme-içme</h2><span class="small muted">Eylem harcamaz · günde 3</span></div><p class="small muted">Yalnızca izin günlerinde. ${esc(NAT[S.nation].n)} lezzetleri zihnini toparlar.</p>
 <div style="display:flex;flex-direction:column;gap:8px">${CF.map((f,i)=>`<button class="opt" data-a="eat" data-v="${i}" ${S.eat[i]===S.day||S.money<f[2]?'disabled':''} style="padding:10px 12px"><span class="k" style="width:30px;height:30px">${S.eat[i]===S.day?'✓':'🍽'}</span><span class="grow"><b>${esc(f[0])}</b><br><span class="small muted">${esc(f[1])}</span><br><span class="small"><span class="green">Ruh hali +${f[3]}</span> · ${money(f[2])}</span></span></button>`).join('')}</div></div>`
 :`<div class="card"><div class="sec-h"><h2>Dış dünya</h2>${ico('lock',18)}</div><p class="small muted">${S.world.war?'Savaş sürüyor: tüm izinler kaldırıldı.':`Dışarı çıkmak, şehirde yemek ve yeni insanlarla tanışmak için izin günü gerekir. Haftalık iznin Pazar günü${S.leave>0?`; ayrıca ${S.leave} gün ödül iznin var`:''}.`}</p>${S.leave>0&&!S.world.war&&!S.izinNext?'<button class="btn ghost block" data-a="useleave">Yarın ödül iznimi kullan</button>':S.izinNext?'<p class="small green">Yarın izinlisin.</p>':''}</div>`;
 return plansCard()+out+`<div class="card"><div class="sec-h"><h2>Arkadaşlar</h2><span class="small muted">${fr.length} kişi</span></div>${fr.length?fr.map((f,i)=>`<div class="row" style="border-bottom:1px solid var(--line);padding-bottom:9px"><span class="ico" style="width:40px;height:40px;border-radius:50%;display:grid;place-items:center;background:color-mix(in srgb,var(--acc) 16%,transparent);color:var(--acc);font:700 16px var(--font-c)">${esc(f.n[0])}</span><div class="grow"><b>${esc(f.n)}</b><div class="small muted">${esc(f.job)}</div><div class="bar" style="grid-template-columns:60px 1fr 30px"><span class="small">Bağ</span><div class="t"><i style="width:${f.b}%;background:var(--blue)"></i></div><span class="v">${Math.round(f.b)}</span></div></div><div class="fbtn"><button class="mini b" data-a="friend" data-v="${i}" ${!S.izin||f.last===S.day?'disabled':''}>Buluş</button>${canLove2()?`<button class="mini r" data-a="confess" data-v="${i}" ${f.b<45||(f.cf||-99)>S.day-7?'disabled':''}>♥ Teklif</button>`:''}</div></div>`).join(''):'<p class="small muted">Henüz kışla dışından arkadaşın yok. İzin günlerinde etkinliklere katıl.</p>'}</div>
 <div class="card"><div class="sec-h"><h2>Kışla hayatı</h2><span class="small muted">1 eylem · günde bir kez</span></div>
 <div class="tiles">${Object.entries(SOC).map(([id,[n,e]])=>`<button class="tile" data-a="soc" data-v="${id}" ${S.soc[id]===S.day?'disabled':''}><span class="ico">${ico(id==='kitap'?'book':id==='kart'?'people':id==='gonullu'?'heart':'moon',18)}</span><b>${n}</b><small>${Object.entries(e).map(([k,v])=>STATN[k]+' +'+v).join(' · ')}</small></button>`).join('')}</div></div>`}

