const n8=()=>String(2+Math.floor(R()*28));
function newsBody(t,a,b){const ca=pick(NAT[a].cities)[0],cb=b?pick(NAT[b].cities)[0]:'';return fill(t,{a:NAT[a].n,b:b?NAT[b].n:'',ca,cb,n:n8(),m:String(1+Math.floor(R()*24)),an:pick(ANL8)})}
function hostileNews(){const me=S.nation,W=S.world;const cand=NK.filter(k=>k!==me&&W.war!==k);if(!cand.length)return;
 const w=cand.map(k=>Math.max(.25,1.5-rel(me,k)/60-(allied(me,k)?.5:0)));let s=w.reduce((a,b)=>a+b,0)*R();let x=cand[0];for(let i=0;i<cand.length;i++){s-=w[i];if(s<=0){x=cand[i];break}}
 W.hs=W.hs||[];const fr=HOST8.map((_,i)=>i).filter(i=>!W.hs.includes(i));const hi=fr.length?pick(fr):Math.floor(R()*HOST8.length);W.hs=[...W.hs,hi].slice(-5);const H=HOST8[hi];const nn=n8();
 const mp={x:NAT[x].n,me:NAT[me].n,n:nn};feed(pick(['ulusal','global']),fill(H.h,mp),fill(H.b,mp),[x,me],{h:hi,x,mp});
 setRel(me,x,rel(me,x)-H.sev);W.hos=W.hos||{};W.hos[x]=[...(W.hos[x]||[]).filter(d=>S.day-d<10),S.day];
 if(allied(me,x)){if(H.sev>=18||W.hos[x].length>=2||rel(me,x)<-10)breakAlliance(x,fill(H.h,mp));else feed('global',`${NAT[x].n} ile ${ek(NAT[me].n,'nin')} ittifakı sarsılıyor`,`Analistler, ${ek(NAT[x].n,'nin')} tutumunun ittifakın geleceğini tartışmaya açtığını belirtiyor. Bir sonraki adım ilişkileri kalıcı olarak koparabilir.`,[x,me])}}
function breakAlliance(x,why){const me=S.nation,W=S.world;if(!allied(me,x))return;W.al=W.al.filter(p=>p!==pk(me,x));W.broken=W.broken||{};W.broken[x]=S.day;setRel(me,x,rel(me,x)-10);
 feed('ulusal',`SON DAKİKA: ${NAT[me].n} ile ${NAT[x].n} arasındaki ittifak sona erdi`,`Gerekçe: ${why}. Ortak tatbikatlar iptal edildi, istihbarat paylaşımı durduruldu. ${NAT[x].n} artık potansiyel bir tehdit olarak değerlendiriliyor.`,[me,x]);log('İttifak bozuldu: '+NAT[x].n);
 pushModal({k:'Son dakika',ti:'İttifak bozuldu',art:`<div class="row" style="justify-content:center;gap:18px;padding:14px;align-items:center">${flag(me,64)}<span class="red" style="font:700 30px var(--font-c)">⚡</span>${flag(x,64)}</div>`,body:`<p><b>${esc(NAT[x].n)}</b> ile ittifak sona erdi.</p><p class="small muted">${esc(why)}</p><p class="small">Ortak savunma taahhüdü geçersiz. ${esc(NAT[x].n)} sana karşı harekâtlarda karşı taraf olabilir; ilişki çok düşerse savaş riski doğar. İlişkiler düzelirse diplomatik mektupla yeniden ittifak teklif edebilirsin.</p>`})}
function allyCheck(){const me=S.nation;NK.filter(k=>k!==me&&allied(me,k)).forEach(k=>{const def=BLOCS.some(b=>b.def&&b.m.includes(me)&&b.m.includes(k));if(rel(me,k)<(def?-15:5))breakAlliance(k,'İlişkiler kopma noktasına geldi')})}
function worldNewsDaily(){
 const me=S.nation,W=S.world;const others=NK.filter(k=>k!==me);W.gs8=W.gs8||[];
 const cnt=3+Math.floor(R()*2);for(let i=0;i<cnt;i++){const fr=NEWS8.map((_,j)=>j).filter(j=>!W.gs8.includes(j));const j=fr.length?pick(fr):Math.floor(R()*NEWS8.length);W.gs8=[...W.gs8,j].slice(-16);const g=NEWS8[j];
  const a=R()<.25?me:pick(NK),b=pick(NK.filter(k=>k!==a));const two=g[1].includes('{b}')||g[2].includes('{b}');const ca=pick(NAT[a].cities)[0];const mp={a:NAT[a].n,b:NAT[b].n,ca,n:n8(),m:String(1+Math.floor(R()*24)),an:pick(ANL8)};if(g[3])g[3](a,b);feed(g[0],fill(g[1],mp),fill(g[2],mp),two?[a,b]:[a])}
 if(R()<.4){const GA=GUN.concat(GUN2);const g=pick(GA);const a=pick(NK),b=pick(NK.filter(k=>k!==a));if(g[3])g[3](a,b);feed(g[0],fill(g[1],{a:NAT[a].n,b:NAT[b].n,n:n8()}),fill(g[2],{a:NAT[a].n,b:NAT[b].n}),[a,b].filter((x,j)=>g[1].includes('{b}')||j===0))}
 (W.wars||[]).slice(0,2).forEach(w=>{if(R()<.6)feed('saha',`${NAT[w.a].n}–${NAT[w.b].n} cephesinde ${w.d}. gün`,pick([`Cepheden gelen bilgilere göre ${ek(NAT[w.a].n,'nin')} zırhlı birlikleri ${pick(NAT[w.b].cities)[0]} yönünde ilerleme kaydetti.`,`Gece boyunca süren topçu düellosunda iki taraf da ağır kayıp verdi. Sivillerin tahliyesi sürüyor.`,`Arabulucu ülkeler ateşkes için yeni bir formül üzerinde çalışıyor; taraflar şimdilik mesafeli.`]),[w.a,w.b])});
 const live=BLOCS.filter(b=>b.def&&b.m.every((x,i)=>b.m.slice(i+1).every(y=>allied(x,y))));if(live.length&&R()<.2){const b=pick(live);feed('global',`${b.n} zirvesi toplandı`,`Zirvede ${b.m.map(k=>NAT[k].n).join(', ')} liderleri ortak savunma planlarını ve İHA/siber tehditlere karşı işbirliğini görüştü.`,b.m)}
 if(R()<.28)hostileNews();
 else if(R()<.5){const AR=RESPA();W.rs=W.rs||[];const cand=AR.filter((x,i)=>!W.rs.includes(i));const t=pick(cand.length?cand:AR);W.rs=[...W.rs,AR.indexOf(t)].slice(-6);const x=pick(others.filter(k=>t.h.includes('ortak tatbikat')?rel(me,k)>0:true))||pick(others);feed(pick(['ulusal','global']),fill(t.h,{x:NAT[x].n,me:NAT[me].n}),'Ülkenin vereceği cevap, ikili ilişkileri ve bölgedeki dengeyi etkileyecek.',[x,me],{t:RESPA().indexOf(t),x})}
 if(S.rank<NEWSR)govAuto();
 (W.feed||[]).forEach(f=>{if(f.r&&!f.done&&S.day-f.d>4){f.done='Yanıt verilmedi';f.exp=1;setRel(me,f.r.x,rel(me,f.r.x)-2)}});
 allyCheck()}
function respOpts(f){if(!f.r)return[];if(f.r.h!=null){const H=HOST8[f.r.h];return H.o.map(([t,e])=>[fill(t,f.r.mp||{}),e])}const t=RESPA()[f.r.t];return t?t.o:[]}
function respond(v){const[id,i]=v.split('|');const it=(S.world.feed||[]).find(f=>f.id===id);if(!it||it.done||!it.r)return;const o=respOpts(it)[+i];if(!o)return;respApply(it,o[0],o[1])}
function respApply(it,txt,e){const x=it.r.x,me=S.nation;
 if(e.rel)setRel(me,x,rel(me,x)+e.rel);if(e.trust)S.trust=clamp(S.trust+e.trust);if(e.pw)S.world.p[me]+=e.pw;if(e.hirs)addSt('hirs',e.hirs);if(e.strat)addSt('strat',e.strat);
 it.done=txt;S.world.fu=[...(S.world.fu||[]),{d:S.day+1,x,dr:e.rel||0,ans:txt.length>80?txt.slice(0,78)+'…':txt}];feed('ulusal',`${ek(NAT[me].n,'den')} ${ek(NAT[x].n,'e')} yanıt`,`Resmî açıklama: "${txt}"`,[me,x]);
 if(allied(me,x)&&(e.rel||0)<=-8&&rel(me,x)<0)breakAlliance(x,'Karşılıklı sert açıklamalar ittifakı bitirdi');
 toast('Ülkenin yanıtı açıklandı. İlişki '+((e.rel||0)>=0?'+':'')+(e.rel||0));save();render()}
const POSW8=['barış','diyalog','işbirliği','iş birliği','görüş','teşekkür','dost','ortak','müzakere','saygı','anlayış','çözüm','itidal','birlikte','yardım','destek','kardeş','güven','sakin','uzlaş'];
const NEGW8=['yalan','kabul edilemez','tehdit','misilleme','karşılık','savaş','düşman','iftira','hesap','bedel','ihanet','saldırı','asla','utanç','alçak','pişman','cezalandır','yok ed','haddini'];
const FIRMW8=['kanıt','hukuk','egemenlik','soruşturma','şeffaf','belge','uluslararası','kayıt','anlaşma','kural'];
function sentiment8(t){const s=t.toLocaleLowerCase('tr');const c=L=>L.reduce((a,w)=>a+(s.split(w).length-1),0);const p=c(POSW8),n=c(NEGW8),f=c(FIRMW8);return{p,n,f,score:p*3-n*4}}
function respWrite(id){if(S.rank<NEWSR)return toast('Ülke adına yanıt vermek için Yüzbaşı rütbesi gerekir.');const it=(S.world.feed||[]).find(f=>f.id===id);if(!it||it.done)return;const el=document.getElementById('rw_'+id);const txt=(el&&el.value||'').trim();if(txt.length<12)return toast('Biraz daha yaz: en az bir cümle.');
 const s=sentiment8(txt);const relD=clamp(s.score+(txt.length>120?1:0),-15,10);const e={rel:relD,trust:Math.min(3,s.f)+(s.n>2?-1:0),hirs:s.n>0?1:0};const tone=relD>=4?'uzlaşmacı':relD<=-6?'sert':'kararlı';
 respApply(it,txt.replace(/\s+/g,' '),e);setTimeout(()=>pushModal({k:'Yazılı açıklama',ti:'Açıklaman yayımlandı',body:`<p class="small muted">Dünya basını açıklamanı <b>${tone}</b> olarak yorumladı.</p><div class="letter mini"><b>${esc(NAT[S.nation].n)} resmî açıklaması</b><p>"${esc(txt)}"</p></div><div class="fx"><span class="${relD>=0?'p':'n'}">İlişki ${relD>=0?'+':''}${relD}</span>${e.trust>0?`<span class="p">Güven +${e.trust}</span>`:''}</div>`}),0)}
function vNews(){const F=S.world.feed||[];const ch=UI.nch||'hepsi';const pend=F.filter(f=>f.r&&!f.done);let L=ch==='bekleyen'?pend:F.filter(f=>ch==='hepsi'||f.ch===ch);if(ch==='hepsi')L=[...pend,...L.filter(f=>!pend.includes(f))];
 return `<div class="row wrap" style="gap:6px"><button class="mini ${ch==='hepsi'?'on':''}" data-a="nch" data-v="hepsi">Tümü</button>${pend.length&&S.rank>=NEWSR?`<button class="mini ${ch==='bekleyen'?'on':''}" data-a="nch" data-v="bekleyen" style="${ch==='bekleyen'?'':'color:var(--red)'}">Cevap bekleyen (${pend.length})</button>`:''}${Object.entries(CHN).map(([k,[n,c]])=>`<button class="mini ${ch===k?'on':''}" data-a="nch" data-v="${k}"><i style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${c};margin-right:5px"></i>${n}</button>`).join('')}</div>
 ${L.length?L.slice(0,24).map(f=>{const op=respOpts(f);return`<div class="card news ${f.r&&!f.done?'pend':''}"><div class="row" style="justify-content:space-between"><span class="chan" style="--c:${CHN[f.ch][1]}">${esc(CHN[f.ch][0])}</span><span class="small muted num">${f.h.startsWith('SON DAKİKA')?'<b class="red">SON DAKİKA</b> · ':''}Gün ${f.d}</span></div><b class="nh">${esc(f.h.replace(/^SON DAKİKA: /,''))}</b>${f.b?`<p class="small muted">${esc(f.b)}</p>`:''}${f.c.length?`<div class="row" style="gap:4px">${f.c.map(k=>NAT[k]?flag(k,20):'').join('')}</div>`:''}
 ${f.r?(f.done?`<div class="small ${f.exp?'red':'green'}">${f.exp?'Yanıt verilmedi; ilişki zarar gördü.':(f.gov?'Hükümetin yanıtı: ':'Ülkenin yanıtı: ')+esc(f.done)}</div>`:S.rank<NEWSR?`<div class="lockn">${ico('lock',14)} <span>Ülke adına yanıt vermek <b>${esc(rankName(NEWSR,S.nation,B().rs))}</b> rütbesinde açılır. Şimdilik bu kararı hükümet ve Genelkurmay verecek; sen haberi takip et.</span></div>`:`<div class="sec-t">Ülkenin yanıtı ne olsun?</div><div style="display:flex;flex-direction:column;gap:6px">${op.map((o,i)=>`<button class="opt" data-a="resp" data-v="${f.id}|${i}" style="padding:10px 12px"><span class="k" style="width:26px;height:26px">${'ABCD'[i]}</span><span class="grow small">${esc(o[0])}</span></button>`).join('')}</div>
 <details class="rwd"><summary>Kendi sözlerinle yaz</summary><textarea id="rw_${f.id}" rows="3" maxlength="400" placeholder="Örn: Bu iddialar asılsızdır. Kanıtlarımızı uluslararası kamuoyuyla paylaşacağız; diyaloğa kapımız açık."></textarea><div class="row" style="justify-content:space-between"><span class="small muted">Üslubun ilişkiyi belirler: uzlaşmacı, kararlı ya da sert.</span><button class="mini b" data-a="respw" data-v="${f.id}">Açıklamayı yayımla</button></div></details><p class="small muted">Yanıt için ${Math.max(0,5-(S.day-f.d))} gün var.</p>`):''}</div>`}).join(''):'<p class="muted">'+(F.length?'Bu kanalda haber yok.':'Henüz haber yok. Günü bitirdiğinde ilk bülten gelir.')+'</p>'}`}

/* ---------- Mektup: kendi sözlerinle ---------- */
function letterTone(k,pid){pushModal({k:'Diplomatik mektup · '+NAT[k].n,ti:'Üslup',body:`<p class="small muted">${esc(LETP.find(p=>p[0]===pid)[1])} · Üslup, cevabı doğrudan etkiler.</p>`,ch:LETT.map(([id,n])=>({t:n,fn:()=>setTimeout(()=>letterSend(k,pid,id),0)})).concat([{t:'Kendi sözlerimle yazacağım',fn:()=>setTimeout(()=>letterWrite(k,pid),0)}])})}
function letterWrite(k,pid){pushModal({k:'Diplomatik mektup · '+NAT[k].n,ti:'Mektubunu yaz',art:`<div class="letter"><div class="seal">${flag(S.nation,30)}</div><div class="lh">${esc(NAT[S.nation].n)} ${S.rank>=14?'Genelkurmayı':'Askerî Ataşeliği'}<br><span>Alıcı: ${esc(NAT[k].n)} Dışişleri Bakanlığı</span></div><textarea id="ltx" rows="6" maxlength="600" placeholder="Sayın Bakan,"></textarea><div class="sig">${esc(myRank())} ${esc(S.name)}</div></div>`,body:'<p class="small muted">Sözcük seçimin mektubun tonunu belirler. Barış, diyalog, işbirliği gibi ifadeler ilişkiyi yumuşatır; tehdit ve suçlama sertleştirir.</p>',ch:[{t:'Mühürle ve gönder',fn:()=>{const t=(document.getElementById('ltx')||{}).value||'';const s=sentiment8(t);const tid=s.score>=3?'sicak':s.score<=-4?'sert':'resmi';if(t.trim().length<15){toast('Mektup çok kısa; resmî üslupla gönderildi.')}S.letMine=t.trim();setTimeout(()=>letterSend(k,pid,tid),0)}},{t:'Vazgeç',fn:()=>{}}]})}

